wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only a published digest has shown its items to anyone, so only then
        // are its considered ids marked seen. An unpublished digest records nothing.
        if published.published {
            for id in published.considered.iter() {
                // Ids are parser-computed digests, safe to use as store keys.
                // Count only ids not already present, so re-runs are idempotent.
                if state_rw::get(id).is_none() {
                    state_rw::put(id, "seen");
                    recorded = recorded.saturating_add(1);
                }
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
